size(31, 107, 7, 1.25);
name("knightly longsword");

var CX = 15, CZ = 3;

// ---------- blade (point down, y 0..77) ----------
function halfW(y) {
  if (y < 10) return Math.round(y / 10 * 2);
  return Math.round(2 + (y - 10) / 68 * 1.5);
}
for (var y = 0; y < 78; y++) {
  var h = halfW(y);
  for (var dx = -h; dx <= h; dx++) {
    var edge = Math.abs(dx) === h;
    var col = edge ? "grey:1" : (rng() < 0.25 ? "grey:3" : "grey:2");
    if (rng() < 0.04) col = "grey:4"; // faint nicks and stains
    put("steel", col, CX + dx, y, CZ);
    if (Math.abs(dx) <= h - 1) {
      var c2 = rng() < 0.3 ? "grey:3" : "grey:2";
      var c3 = rng() < 0.3 ? "grey:3" : "grey:2";
      if (dx === 0 && y >= 22) { c2 = (y % 9 === 0) ? "grey:6" : "grey:5"; c3 = c2; } // fuller
      put("steel", c2, CX + dx, y, CZ - 1);
      put("steel", c3, CX + dx, y, CZ + 1);
    }
  }
}
// fuller ends in a soft fade
put("steel", "grey:4", CX, 21, CZ - 1);
put("steel", "grey:4", CX, 21, CZ + 1);

// ---------- cross-guard (y 78..82) ----------
var G = "3:5", G2 = "3:9", G3 = "3:4";
// arms droop slightly toward the blade
tube("steel", G, 15.5, 80.2, 3.5, 6, 78.8, 3.5, 1.6, 1.2);
tube("steel", G, 15.5, 80.2, 3.5, 25, 78.8, 3.5, 1.6, 1.2);
// ringed terminals
ball("steel", G3, 5.5, 78.6, 3.5, 2.1, 2.1, 2.1);
ball("steel", G3, 25.5, 78.6, 3.5, 2.1, 2.1, 2.1);
for (var z = 2; z <= 4; z++) {
  for (var yy = 77; yy <= 81; yy++) {
    if (at(8, yy, z)) put("steel", G2, 8, yy, z);
    if (at(22, yy, z)) put("steel", G2, 22, yy, z);
  }
}
// centre block
box("steel", G, 12, 78, 1, 19, 82, 6);
box("steel", G2, 12, 78, 1, 19, 79, 6);
box("steel", G3, 13, 81, 1, 18, 82, 6);
// langet tongue down over blade base
box("steel", G2, 14, 76, 1, 17, 78, 6);
put("steel", G2, 15, 75, 1); put("steel", G2, 15, 75, 5);
// gems front and back
put("glass", "0:4", 15, 80, 0); put("glass", "0:4", 15, 80, 6);
put("steel", G3, 14, 80, 0); put("steel", G3, 16, 80, 0);
put("steel", G3, 14, 80, 6); put("steel", G3, 16, 80, 6);
// rivets
put("steel", G2, 10, 80, 1.5 | 0); put("steel", G2, 20, 80, 1);

// ---------- grip (y 82..97) ----------
for (var gy = 82; gy < 98; gy++) {
  var t = (gy - 82) / 15;
  var swell = 1.9 + 0.4 * Math.sin(t * Math.PI);
  var lc = (gy % 3 === 0) ? "2:6" : (rng() < 0.3 ? "2:8" : "2:9");
  ball("plaster", lc, 15.5, gy + 0.5, 3.5, swell, 0.5, 1.9);
  // spiral wire glint
  var a = gy * 1.3;
  var wx = Math.round(15 + Math.cos(a) * 1), wz = Math.round(3 + Math.sin(a) * 1);
  if (at(wx, gy, wz) && gy % 3 === 0) put("steel", "grey:6", wx, gy, wz);
}
// ferrules
ball("steel", G3, 15.5, 82.5, 3.5, 2.6, 0.5, 2.3);
ball("steel", G3, 15.5, 97.5, 3.5, 2.6, 0.5, 2.3);
ball("steel", G2, 15.5, 90.5, 3.5, 2.6, 0.5, 2.3);

// ---------- pommel (y 98..105) ----------
ball("steel", G, 15.5, 101.5, 3.5, 3.6, 3.6, 2.6);
// rim shading: darker ring on face edges
for (var px = 11; px <= 19; px++) {
  for (var py = 98; py <= 105; py++) {
    var d = Math.sqrt((px - 15) * (px - 15) + (py - 101) * (py - 101));
    for (var pz = 1; pz <= 5; pz++) {
      if (!at(px, py, pz)) continue;
      if (d > 2.6) put("steel", G2, px, py, pz);
      else if (d > 1.4 && (pz === 1 || pz === 5)) put("steel", G3, px, py, pz);
    }
  }
}
// inset gems front and back
put("glass", "0:4", 15, 101, 0); put("glass", "0:4", 15, 101, 6);
put("glass", "0:5", 15, 101, 1); put("glass", "0:5", 15, 101, 5);
// peen block on top
box("steel", G2, 15, 105, 3, 16, 106, 4);
put("steel", G3, 15, 106, 3);
